import React, { useState } from 'react';
import { Form, Input, Button, DatePicker, Select, message } from 'antd';
import PhoneInput from 'react-phone-input-2';
import 'react-phone-input-2/lib/style.css';
import { registerUser } from '../../firebase/authService';

const { Option } = Select;

const RegisterForm: React.FC = () => {
  const [phone, setPhone] = useState('');
  const [loading, setLoading] = useState(false);

  const onFinish = async (values: any) => {
    setLoading(true);
    try {
      const result = await registerUser(
        values.email,
        values.password,
        values.fullName,
        phone,
        values.birthDate.format('YYYY-MM-DD'),
        values.gender,
      );

      if (result.success) {
        message.success('Registration successful!');
      } else {
        message.error(result.error);
      }
    } catch (error: any) {
      message.error(error.message || 'Registration failed!');
    } finally {
      setLoading(false); // إعادة تفعيل الزر
    }
  };

  return (
    <div
      style={{
        maxWidth: 450,
        margin: '40px auto',
        padding: 20,
        background: '#fff',
        borderRadius: 8,
      }}
    >
      <Form layout="vertical" onFinish={onFinish} style={{ gap: 8 }}>
        <Form.Item
          name="fullName"
          rules={[{ required: true, message: 'Please enter your full name' }]}
        >
          <Input
            placeholder="Full Name"
            size="small"
            style={{ height: 34, fontSize: 13 }}
          />
        </Form.Item>

        <Form.Item
          name="email"
          rules={[
            {
              required: true,
              type: 'email',
              message: 'Please enter a valid email',
            },
          ]}
        >
          <Input
            placeholder="Email"
            size="small"
            style={{ height: 34, fontSize: 13 }}
          />
        </Form.Item>

        <Form.Item
          name="password"
          rules={[{ required: true, min: 6, message: 'Please enter password' }]}
        >
          <Input.Password
            placeholder="Password"
            size="small"
            style={{ height: 34, fontSize: 13 }}
          />
        </Form.Item>

        <Form.Item
          name="confirmPassword"
          rules={[{ required: true, message: 'Please confirm password' }]}
        >
          <Input.Password
            placeholder="Confirm Password"
            size="small"
            style={{ height: 34, fontSize: 13 }}
          />
        </Form.Item>

        <Form.Item
          name="phone"
          rules={[{ required: true, message: 'Please enter phone number' }]}
        >
          <PhoneInput
            country="us"
            value={phone}
            onChange={setPhone}
            inputStyle={{ height: 34, fontSize: 13, width: '100%' }}
          />
        </Form.Item>

        <Form.Item
          name="birthDate"
          rules={[{ required: true, message: 'Please select birth date' }]}
        >
          <DatePicker
            size="small"
            style={{ width: '100%', height: 34, fontSize: 13 }}
          />
        </Form.Item>

        <Form.Item
          name="gender"
          rules={[{ required: true, message: 'Please select gender' }]}
        >
          <Select
            placeholder="Select Gender"
            size="small"
            style={{ height: 34, fontSize: 13 }}
          >
            <Option value="male">Male</Option>
            <Option value="female">Female</Option>
            <Option value="other">Other</Option>
          </Select>
        </Form.Item>

        <Form.Item>
          <Button
            type="primary"
            htmlType="submit"
            size="small"
            style={{ height: 32, fontSize: 13, width: '100%' }}
            disabled={loading}
          >
            {loading ? 'Registering...' : 'Register'}
          </Button>
        </Form.Item>
      </Form>
    </div>
  );
};

export default RegisterForm;
